using System;using System.IO;using System.Linq;using System.Text;using System.Collections.Generic;using System.Reflection;using UnityEngine;using UnityEngine.SceneManagement;using UnityEditor;using UnityEditor.SceneManagement;
namespace CodexOutTransfer {
public static class GroundOutStones {
const string W="C:/Users/lenovo/Documents/Codex/2026-10-16/new-chat/work/",O="C:/Users/lenovo/Documents/Codex/2026-10-16/new-chat/outputs/";
static string Path(Transform t){return t.parent?Path(t.parent)+"/"+t.name:t.name;}
static bool Stone(MeshRenderer r){string n=r.name.ToLowerInvariant();if(r.transform.root.name=="Foreground - Chipped Stone Groups")return true;return n.Contains("scattered angular rubble")||n.Contains("large fallen concrete slab")||n.Contains("fallen chipped masonry")||n.Contains("broken standing stone")||n.StartsWith("sm_env_rock_");}
sealed class Surface {public Mesh mesh;public Matrix4x4 matrix;public Bounds bounds;public string name;}
static List<Surface> surfaces;static Terrain[] terrains;static MethodInfo intersect;
static bool Height(float x,float z,out float height){height=float.NegativeInfinity;foreach(var t in terrains){var p=t.transform.position;var size=t.terrainData.size;if(x>=p.x&&x<=p.x+size.x&&z>=p.z&&z<=p.z+size.z){float nx=(x-p.x)/size.x,nz=(z-p.z)/size.z;if(!t.terrainData.IsHole(Mathf.Clamp((int)(nx*t.terrainData.holesResolution),0,t.terrainData.holesResolution-1),Mathf.Clamp((int)(nz*t.terrainData.holesResolution),0,t.terrainData.holesResolution-1)))height=Mathf.Max(height,t.SampleHeight(new Vector3(x,0,z))+p.y);}}
foreach(var s in surfaces){if(x<s.bounds.min.x-.01f||x>s.bounds.max.x+.01f||z<s.bounds.min.z-.01f||z>s.bounds.max.z+.01f)continue;var ray=new Ray(new Vector3(x,s.bounds.max.y+2,z),Vector3.down);object[] args={ray,s.mesh,s.matrix,new RaycastHit()};if((bool)intersect.Invoke(null,args)){var hit=(RaycastHit)args[3];if(hit.normal.y>.12f)height=Mathf.Max(height,hit.point.y);}}return !float.IsNegativeInfinity(height);}
static float Clearance(MeshRenderer r,out int samples){samples=0;var filter=r.GetComponent<MeshFilter>();var matrix=filter.transform.localToWorldMatrix;var vertices=filter.sharedMesh.vertices;float bottom=r.bounds.min.y,cut=bottom+r.bounds.size.y*.50f;float clearance=float.PositiveInfinity;var unique=new HashSet<Vector3>();foreach(var v in vertices){var world=matrix.MultiplyPoint3x4(v);if(world.y>cut||!unique.Add(world))continue;float y;if(!Height(world.x,world.z,out y))continue;clearance=Mathf.Min(clearance,world.y-y);samples++;}return clearance;}
static Scene Scene(){var s=SceneManager.GetSceneByPath("Assets/ArtStyleTest/Scenes/out.unity");if(!s.isLoaded||EditorApplication.isPlaying)throw new Exception("Open out in Edit mode");return s;}
static MeshRenderer[] Prepare(Scene s,StringBuilder b){intersect=typeof(HandleUtility).GetMethod("IntersectRayMesh",BindingFlags.Static|BindingFlags.Public|BindingFlags.NonPublic);if(intersect==null)throw new Exception("Mesh surface query unavailable");var renderers=s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<MeshRenderer>(false)).Where(r=>r.enabled&&r.gameObject.activeInHierarchy&&r.GetComponent<MeshFilter>()?.sharedMesh).ToArray();surfaces=new List<Surface>();foreach(var r in renderers){bool ground=r.sharedMaterials.Any(m=>m&&m.shader&&(m.shader.name=="Codex/PainterlyMeadow/Ground"||m.shader.name=="ArtStyleTest/DetailedMeadowLit"));bool platform=r.name=="Cube"&&r.transform.parent&&r.transform.parent.name=="xiangjipingtai";bool grassMesh=r.name.StartsWith("Reference ")||r.name.ToLowerInvariant().Contains("grass")||r.name.ToLowerInvariant().Contains("flower");if((ground&&!grassMesh)||platform){surfaces.Add(new Surface{mesh=r.GetComponent<MeshFilter>().sharedMesh,matrix=r.localToWorldMatrix,bounds=r.bounds,name=Path(r.transform)});}}
terrains=s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Terrain>(false)).Where(t=>t.enabled&&t.drawHeightmap&&t.gameObject.activeInHierarchy&&t.terrainData).ToArray();foreach(var surface in surfaces)b.AppendLine("surface="+surface.name+" bounds="+surface.bounds);foreach(var t in terrains)b.AppendLine("terrain="+t.name+" position="+t.transform.position);var stones=renderers.Where(Stone).ToArray();b.AppendLine("stoneCandidates="+stones.Length);return stones;}
[MenuItem("Tools/Out Scene Transfer/Inspect Floating Stones")]
public static void Inspect(){var b=new StringBuilder();try{var stones=Prepare(Scene(),b);foreach(var r in stones){int samples;float gap=Clearance(r,out samples);if(gap>.04f)b.AppendLine("floating="+Path(r.transform)+" gap="+gap.ToString("F3")+" samples="+samples+" position="+r.transform.position.ToString("F3"));}b.AppendLine("inspected=True");}catch(Exception e){b.AppendLine(e.ToString());Debug.LogException(e);}File.WriteAllText(W+"out_floating_stones_inspect.txt",b.ToString());}
[MenuItem("Tools/Out Scene Transfer/Seat Floating Stones On Ground")]
public static void Apply(){var b=new StringBuilder();try{var scene=Scene();var stones=Prepare(scene,b);string backup="Assets/ArtStyleTest/Scenes_BACKUP/out_before_stones_grounded_"+DateTime.Now.ToString("yyyyMMdd_HHmmss")+".unity";if(!EditorSceneManager.SaveScene(scene,backup,true))throw new Exception("Backup failed");b.AppendLine("backup="+backup);var stoneSet=new HashSet<Transform>(stones.Select(r=>r.transform));var protectedTransforms=scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Transform>(true)).Where(t=>!stoneSet.Contains(t)).ToDictionary(t=>t,t=>t.localToWorldMatrix);Undo.IncrementCurrentGroup();Undo.SetCurrentGroupName("Seat floating stones on existing ground");int moved=0,missing=0;foreach(var r in stones){int samples;float gap=Clearance(r,out samples);if(samples==0){missing++;b.AppendLine("noGround="+Path(r.transform));continue;}if(gap<=.045f)continue;float burial=Mathf.Clamp(r.bounds.size.y*.10f,.018f,.085f);float shift=-gap-burial;var t=r.transform;var before=t.position;Undo.RecordObject(t,"Seat floating stone");t.position+=Vector3.up*shift;EditorUtility.SetDirty(t);moved++;int count;float after=Clearance(r,out count);b.AppendLine("moved="+Path(t)+" beforeGap="+gap.ToString("F4")+" afterGap="+after.ToString("F4")+" from="+before.ToString("F3")+" to="+t.position.ToString("F3"));if(after>.05f)throw new Exception("Stone did not reach ground: "+t.name);}
foreach(var p in protectedTransforms){var after=p.Key.localToWorldMatrix;for(int i=0;i<16;i++)if(Mathf.Abs(p.Value[i]-after[i])>.001f)throw new Exception("Non-stone moved: "+Path(p.Key));}
EditorSceneManager.MarkSceneDirty(scene);if(!EditorSceneManager.SaveScene(scene))throw new Exception("Save failed");SceneView.RepaintAll();var camera=scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Camera>(true)).First(c=>c.transform.parent&&c.transform.parent.name=="xiangjipingtai");typeof(OutReferenceComposition).GetMethod("Capture",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,new object[]{camera,O+"Out_stones_grounded.png"});b.AppendLine("moved="+moved+" noGround="+missing+" nonStoneTransformsUnchanged=True cameraGroundLightingUntouched=True saved=True");}catch(Exception e){b.AppendLine(e.ToString());Debug.LogException(e);}File.WriteAllText(W+"out_stones_grounded_result.txt",b.ToString());}
}
}
